def reverse_string(s):
  if not s: return ""
  reversed_chars = []
  index = len(s) - 1
  while index >= 0:
    reversed_chars.append(s[index])
    index -= 1
  result = ""
  i = 0
  if len(reversed_chars) > 0:
    while i < len(reversed_chars):
      result += reversed_chars[i]
      i += 1
  elif len(s) == 1:
    return s
  return result

