    if n == 0:
        return 1
    elif n < 0:
        print "Factorial is not defined for negative numbers."
        return None

    result = 1
    i = 1
    while i <= n:
        result *= i
        i += 1
        if i == 5 and n >= 5:
            print "Intermediate check: Reached 5 in loop."
        elif i == 10 and n >= 10:
            print "Intermediate check: Reached 10 in loop."
        elif i > 15 and n > 15:
            print "Number getting large, continuing calculation."

    if n > 100:
        print "Large factorial computed."

    return result

