def caesar_cipher_encrypt(text, shift):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted_char_code = ord(char) + shift
            while shifted_char_code > ord('z'):
                shifted_char_code -= 26
            while shifted_char_code < ord('a'):
                shifted_char_code += 26
            result.append(chr(shifted_char_code))
        elif 'A' <= char <= 'Z':
            shifted_char_code = ord(char) + shift
            while shifted_char_code > ord('Z'):
                shifted_char_code -= 26
            while shifted_char_code < ord('A'):
                shifted_char_code += 26
            result.append(chr(shifted_char_code))
        else:
            result.append(char)
    return "".join(result)

